update wkf_supply_request
set status_enum = 'PENDING_APPROVAL',
    applicant_id = #{applicantId},
    apply_time = #{applyTime},
    approver_id = #{approverId},
    approval_time = null,
    reason = null,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where bus_no = #{busNo}
  and type_enum = #{typeEnum}
  and status_enum = #{currentStatus}
  and is_deleted = 0

update wkf_supply_request
set status_enum = 'WITHDRAW',
    approver_id = null,
    approval_time = null,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where bus_no = #{busNo}
  and type_enum = #{typeEnum}
  and status_enum = #{currentStatus}
  and is_deleted = 0

update wkf_supply_request
set status_enum = 'AGREE',
    approver_id = #{approverId},
    approval_time = #{approvalTime},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where bus_no = #{busNo}
  and type_enum = #{typeEnum}
  and status_enum = #{currentStatus}
  and is_deleted = 0

update wkf_supply_request
set status_enum = 'REJECT',
    approver_id = #{approverId},
    approval_time = #{approvalTime},
    reason = #{reason},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
where bus_no = #{busNo}
  and type_enum = #{typeEnum}
  and status_enum = #{currentStatus}
  and is_deleted = 0

mapper.select:
SELECT t.bus_no, t.type_enum, t.status_enum, t.source_location_id,t.purpose_location_id, t.apply_time, t.approval_time, t.occurrence_time, t.applicant_id, t.created_by, t.approver_id, t.original_bus_no,sub.total_amount FROM wkf_supply_request t INNER JOIN ( SELECT MIN(id) min_id,bus_no, SUM(total_price) AS total_amount FROM wkf_supply_request WHERE is_deleted = 0
AND bus_no LIKE CONCAT('%', #{query.keyword}, '%')
AND created_at >= #{query.applyTimeFrom}
AND created_at <= #{query.applyTimeTo}
AND purpose_location_id = #{query.purposeLocationId}
AND source_location_id = #{query.sourceLocationId}
GROUP BY bus_no ) sub ON t.id = sub.min_id ORDER BY t.created_at DESC

